var TECH=[["Dependency graph builds", "Rebuilding only what changed by tracking file-level dependencies."], ["Hermetic builds", "Isolating builds from ambient machine state so outputs are reproducible."], ["Scaffolding", "Generating a working project skeleton so new work starts from a known-good layout."], ["Monorepo layouts", "One repository holding many packages with shared tooling and atomic cross-package changes."], ["Lockfiles", "Pinning exact dependency versions so installs reproduce byte-identically."], ["Workspace templates", "Parameterized directory trees with placeholder substitution."], ["Build caching", "Reusing prior outputs keyed by input hashes to skip redundant work."], ["Out-of-source builds", "Keeping generated artifacts out of the source tree for clean checkouts."], ["Conventional layouts", "src, tests and docs directory contracts that tools can rely on."], ["Environment pinning", "Locking interpreter and toolchain versions per project with nvm, rustup or pyenv."]];
